'use client';

import { useState } from 'react';
import { api, errorMessage } from '@globalantic/api-client';
import { Alert, AsyncView, Button, PageHeader, Pagination, Tabs, formatDateTime, useAsync, useToast } from '@globalantic/ui';
import s from '@/components/page.module.css';
import { usePageTitle } from '@/components/usePageTitle';

const PAGE_SIZE = 20;

/** Notification links are generated by the server; only http(s) links are rendered. */
function safeLink(link: string | null): string | null {
  if (!link) return null;
  if (link.startsWith('/')) return link;
  try {
    const u = new URL(link);
    return u.protocol === 'https:' || u.protocol === 'http:' ? u.toString() : null;
  } catch {
    return null;
  }
}

export default function NotificationsPage() {
  usePageTitle('Notifications');
  const toast = useToast();
  const [page, setPage] = useState(1);
  const [filter, setFilter] = useState<'all' | 'unread'>('all');
  const state = useAsync(() => api().student.notifications({ page, pageSize: PAGE_SIZE, unread: filter === 'unread' }), `notifications-${page}-${filter}`);
  const [error, setError] = useState<string | null>(null);

  const markRead = async (ids: string[] | 'all') => {
    setError(null);
    try {
      const r = await api().student.markNotificationsRead(ids);
      if (ids === 'all') toast(r.updated ? `Marked ${r.updated} as read` : 'Everything is already read');
      state.reload();
    } catch (err) {
      setError(errorMessage(err));
    }
  };

  return (
    <div className={s.stack}>
      <PageHeader
        title="Notifications"
        description="Updates about your applications, payments, classes and rewards."
        actions={
          <Button variant="outline" size="sm" onClick={() => void markRead('all')} disabled={!state.data?.unread}>
            Mark all as read
          </Button>
        }
      />
      {error && <Alert tone="danger">{error}</Alert>}
      <Tabs
        label="Filter notifications"
        value={filter}
        onChange={(v) => {
          setFilter(v);
          setPage(1);
        }}
        items={[
          { value: 'all', label: 'All' },
          { value: 'unread', label: 'Unread', count: state.data?.unread },
        ]}
      />
      <AsyncView state={state} isEmpty={(d) => d.items.length === 0} empty={{ title: filter === 'unread' ? 'You are all caught up' : 'No notifications yet' }}>
        {(d) => (
          <>
            <ul className={s.list}>
              {d.items.map((n) => {
                const href = safeLink(n.link);
                return (
                  <li key={n.id} className={`${s.item} ${!n.readAt ? s.unread : ''}`}>
                    <div className={s.between}>
                      <span className={s.title}>
                        {!n.readAt && <span className="sr-only">Unread: </span>}
                        {n.title}
                      </span>
                      <span className={s.small}>{formatDateTime(n.createdAt)}</span>
                    </div>
                    <p className={s.body}>{n.body}</p>
                    <div className={s.row}>
                      {href && (
                        <a href={href} className={s.link} onClick={() => !n.readAt && void markRead([n.id])}>
                          Open
                        </a>
                      )}
                      {!n.readAt && (
                        <Button variant="ghost" size="sm" onClick={() => void markRead([n.id])}>
                          Mark as read
                        </Button>
                      )}
                    </div>
                  </li>
                );
              })}
            </ul>
            <Pagination page={page} totalPages={Math.max(1, Math.ceil(d.total / PAGE_SIZE))} onChange={setPage} />
          </>
        )}
      </AsyncView>
    </div>
  );
}
